"""Build the offline academic-v3 figure gallery from rendered scientific assets."""
from pathlib import Path
import base64,json,hashlib
B=Path(__file__).resolve().parent;F=B.parents[1]/'figures';O=B.parents[2]/'output/html';O.mkdir(parents=True,exist_ok=True)
items=[
('fig17_obs_combinations','Observation combinations','physics','Means and population standard deviations for the three observation combinations.'),
('fig16_fixed_astro_bt_histories','Fixed-galaxy BT histories','physics','Five coeval histories and the same-node differences at fixed galaxy parameters.'),
('fig5_21cmtb_histories','Atlas histories','physics','Original atlas nodes, matched PL reference and direct BT-minus-PL differences.'),
('fig6_21cmtb_lf_grid','Luminosity-function fits','physics','Stored LF maxima across the spectral grid, with a magnified near-PL comparison.'),
('fig7_21cmtb_lf_fits','Luminosity functions by redshift','physics','Original best-fit curves and all 34 selected observed data points.'),
('fig15_kpms_focus','Spectrum coordinates','inference','The same 32-bin kp/MS histogram and 89,088 retained rows as the archived 8D corner.'),
('fig11_btemu_corner6_5000','6D fixed-spectrum sample','inference','Archived earlier predictor. Last half of 5,000 stored steps: 80,000 correlated rows.'),
('fig12_btemu_corner8_5568','8D free-spectrum sample','inference','Archived earlier predictor. Last half of 5,568 stored steps: 89,088 correlated rows.'),
('fig13_exact_corner6_200','Exact 200-step sample','inference','All 6,400 stored rows of the unconverged exact smoke chain.'),
('fig14_validation','History prediction accuracy','validation','The same 512 development histories, selected rank examples and signed residuals.'),
('fig10_21cmtb_diagnostics','Archived sampling diagnostics','validation','Reported rank/folded and autocorrelation checks for the older exact ensembles.'),
('fig8_21cmtb_corner_fixed8','Historical exact 8D sample','inference','Eight galaxy coordinates. Two archived ensembles; 64,000 retained rows.'),
('fig9_21cmtb_corner_free9','Historical exact 9D sample','inference','Eight galaxy coordinates and free MS. Two archived ensembles; 12,800 rows.')]
cards=[];manifest={}
for name,title,group,note in items:
 p=F/(name+'.png');pdf=F/(name+'.pdf');raw=p.read_bytes();png='data:image/png;base64,'+base64.b64encode(raw).decode();doc='data:application/pdf;base64,'+base64.b64encode(pdf.read_bytes()).decode()
 manifest[name]={'png_sha256':hashlib.sha256(raw).hexdigest(),'pdf_sha256':hashlib.sha256(pdf.read_bytes()).hexdigest()}
 cards.append(f'<article data-group="{group}"><div class="card-head"><h2>{title}</h2><a href="{doc}" download="{name}.pdf">Vector PDF</a></div><button class="figure" aria-label="Enlarge {title}"><img src="{png}" alt="{title}" loading="lazy"></button><p>{note}</p></article>')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>BTemu | Academic figure collection</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f5f8;color:#243447;font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-width:1080px}header,main,footer{max-width:1460px;margin:auto;padding:32px 40px}header{padding-top:48px}h1{font:normal 36px/1.3 Georgia,serif;margin:0 0 12px}header p{color:#566574;max-width:85ch}.key{display:flex;gap:24px;margin:20px 0;color:#566574}.key span::before{content:"";display:inline-block;width:18px;height:3px;margin-right:8px;vertical-align:middle;background:var(--c)}nav{display:flex;gap:10px;margin-top:24px}button{font:inherit;cursor:pointer}nav button{background:white;color:#315E8B;border:1px solid #bdcbd7;border-radius:5px;padding:7px 18px}nav button[aria-pressed=true]{color:white;background:#315E8B;border-color:#315E8B}main{padding-top:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}article{background:white;border:1px solid #dce4ec;border-radius:7px;padding:24px;break-inside:avoid}article[hidden]{display:none}.card-head{display:flex;align-items:baseline;justify-content:space-between;gap:15px}h2{font:normal 21px/1.4 Georgia,serif;margin:0 0 20px}a{color:#315E8B;text-underline-offset:3px;white-space:nowrap;font-size:13px}.figure{display:block;width:100%;padding:0;border:0;background:white}.figure img{display:block;width:100%;height:auto;max-height:690px;object-fit:contain}article p{font-size:13px;color:#566574;margin:18px 0 0}footer{color:#566574;font-size:13px}dialog{width:96vw;max-width:96vw;height:95vh;border:1px solid #a4b5c5;padding:16px;border-radius:8px}dialog::backdrop{background:#172c4266}.close{border:1px solid #a4b5c5;background:white;border-radius:5px;padding:6px 16px}#full{max-width:none;width:auto;height:auto}.viewport{height:calc(100% - 50px);overflow:auto;margin-top:10px}:focus-visible{outline:3px solid #6f9db3;outline-offset:3px}@media print{body{min-width:0;background:white}.grid{display:block}article{margin-bottom:24px}nav,.close{display:none}header,main,footer{padding:15px}}
</style></head><body><header><h1>BTemu figure collection</h1><p>A unified academic layout for histories, luminosity functions, sample distributions and validation. Original source values, retained rows and statistical definitions are preserved.</p><div class="key"><span style="--c:#315E8B">Deep blue</span><span style="--c:#278579">Teal</span><span style="--c:#BE624F">Vermilion</span><span style="--c:#AA843B">Ochre</span></div><nav aria-label="Filter figures"><button data-filter="all" aria-pressed="true">All 13 figures</button><button data-filter="physics" aria-pressed="false">Physical results</button><button data-filter="inference" aria-pressed="false">Samples and corners</button><button data-filter="validation" aria-pressed="false">Validation</button></nav></header><main><div class="grid">'''+''.join(cards)+'''</div></main><footer>4 November 2026 · Academic-v3 · Click any figure for its original resolution. Scientific sample status is retained in the captions.</footer><dialog id="viewer"><button class="close" onclick="document.getElementById('viewer').close()">Close image</button><div class="viewport"><img id="full" alt=""></div></dialog><script>
const viewer=document.getElementById('viewer'),full=document.getElementById('full');document.querySelectorAll('.figure').forEach(button=>button.addEventListener('click',()=>{full.src=button.querySelector('img').src;full.alt=button.querySelector('img').alt;viewer.showModal()}));document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('article').forEach(a=>a.hidden=button.dataset.filter!=='all'&&a.dataset.group!==button.dataset.filter)}));</script></body></html>'''
p=O/'BTemu_figures_20261104.html';p.write_text(html);(B/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(p,p.stat().st_size)
